$ErrorActionPreference="Stop";$root=(Resolve-Path -LiteralPath (Join-Path $PSScriptRoot "..\..")).Path
$hostName=if($env:MYSQL_HOST){$env:MYSQL_HOST}else{"localhost"};$port=if($env:MYSQL_PORT){$env:MYSQL_PORT}else{"3306"};$username=if($env:MYSQL_USERNAME){$env:MYSQL_USERNAME}else{"root"};$password=if($null-ne$env:MYSQL_PASSWORD){$env:MYSQL_PASSWORD}else{""};$container=if($env:MYSQL_CONTAINER){$env:MYSQL_CONTAINER}else{"apihub-mysql"}
. (Join-Path $PSScriptRoot "mysql-file-utils.ps1")
foreach($relative in @("scripts\sql\validate-demo-data.sql","scripts\sql\validate-t15-incremental.sql","scripts\sql\validate-t16-incremental.sql","scripts\sql\validate-t17-incremental.sql")){$path=Join-Path $root $relative;$out=Invoke-MySqlSqlFile -Path $path -HostName $hostName -Port $port -Username $username -Password $password -ContainerName $container -Capture;$out|ForEach-Object{Write-Host $_};$bad=$out|Where-Object{$_-match'^[^\t]+\t([1-9][0-9]*)$'-and$_-notmatch'^demo_'};if($bad){throw "$relative found anomalies: $($bad-join'; ')"}}
$python=Get-Command python -ErrorAction SilentlyContinue;if($python-and$python.Source-notlike"*WindowsApps*"){&$python.Source (Join-Path $root "scripts\data\validate-demo-data.py")}elseif(Get-Command py -ErrorAction SilentlyContinue){&py -3 (Join-Path $root "scripts\data\validate-demo-data.py")}else{throw "Python is unavailable"};if($LASTEXITCODE-ne0){throw "Python demo validation failed"};Write-Host "Complete demo validation passed"
